import{z as i,x as s,o as A,c as l,q as e,j as r,D as a,d as n,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"账户绩效收束","description":"","frontmatter":{"title":"账户绩效收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ap-map.md","filePath":"quant/ap-map.md","lastUpdated":1791413859000}'),p={name:"quant/ap-map.md"};function d(h,E,u,m,f,C){const t=s("Mermaid");return A(),l("div",null,[E[2]||(E[2]=e('<h1 id="账户绩效收束" tabindex="-1">账户绩效收束 <a class="header-anchor" href="#账户绩效收束" aria-label="Permalink to &quot;账户绩效收束&quot;">​</a></h1><div class="epigraph"><p>评价先于改进，口径先于评价：一张能复算的费用表、一条能重述的净值、一套事先指定的基准，比任何两位小数的年化都更接近「说得清」。</p><footer>—— 据 CFA Institute, Global Investment Performance Standards（GIPS）与绩效评估实务整理；主动算术见 Sharpe, Financial Analysts Journal, 1991</footer></div><p><a href="/quant/ap-investor-behavior-drag">上一课</a>把镜头从产品拉回持有人，用 MWR 对 TWR 的缺口合上了评估的最后一块。本课程到此收束。八课从「收益怎么算」走到「数字归谁」：核算单元立口径，评估单元立判据，本课把它们合回一张图，并标出与已修课程的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>合起来要回答一个问题：<strong>一份账户绩效报告能否从逐笔账本复算到每一个结论</strong>，中途不经过任何人的裁量。链条是：<a href="/quant/ap-return-accounting">收益的核算口径</a>给毛净两遍的收益数；<a href="/quant/ap-fee-taxonomy">费用结构的分类</a>给逐层可复算的瀑布；<a href="/quant/ap-nav-construction">净值曲线的构造</a>给可重述的测量仪器；<a href="/quant/ap-riskadjusted-family">风险调整绩效的族谱</a>把曲线压成与契约匹配的效率数；<a href="/quant/ap-benchmark-selection">基准选择的争议</a>钉住差分的减数；<a href="/quant/ap-performance-persistence">绩效的持续性</a>给时间维度的证据及其设计约束；<a href="/quant/ap-investor-behavior-drag">投资者行为损耗</a>给持有人实收的对账。任一环断了——口径混用、科目漏记、曲线不可重述、基准事后换——下游就用猜补齐，猜出来的「年化 15.3%」没有审计价值。</p><p><span class="marginnote">术语翻译：「复算」就是不听取任何人的口头解释，只拿原始账本、估值源与书面规则，让第三方独立重算出同一个数。能复算的报告才谈得上审计与 comparability（可比）；否则每个数字背后都站着一位「你得出示抗议才肯解释」的人。</span></p><p><span class="marginnote">验收沿用作市课的三问：这个数从哪来（账本与估值源）、谁改过（修订与基准变更留痕）、依据哪条规则（事前书面契约）。三问都指向文件，报告才立得住。</span></p>',7)),(A(),r(o,null,{default:a(()=>[B(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E6%A0%B8%E7%AE%97%E5%8F%A3%E5%BE%84%3A%20%E6%AF%9B%E5%87%80%E4%B8%A4%E9%81%8D%22%5D%20--%3E%20FEE%5B%22%E8%B4%B9%E7%94%A8%E7%80%91%E5%B8%83%3A%20%E9%80%90%E5%B1%82%E7%A7%91%E7%9B%AE%22%5D%0A%20%20FEE%20--%3E%20NAV%5B%22%E5%87%80%E5%80%BC%E6%9B%B2%E7%BA%BF%3A%20%E4%BC%B0%E5%80%BC%E5%88%86%E7%BA%A7%E4%B8%8E%E9%87%8D%E8%BF%B0%22%5D%0A%20%20NAV%20--%3E%20RATIO%5B%22%E6%AF%94%E7%8E%87%E5%A5%97%E8%A3%85%3A%20%E6%8C%89%E5%A5%91%E7%BA%A6%E5%8F%96%E6%99%AF%22%5D%0A%20%20RATIO%20--%3E%20BENCH%5B%22%E5%9F%BA%E5%87%86%E5%A5%91%E7%BA%A6%3A%20%E4%BA%8B%E5%89%8D%E6%8C%87%E5%AE%9A%22%5D%0A%20%20BENCH%20--%3E%20PERSIST%5B%22%E6%8C%81%E7%BB%AD%E6%80%A7%E6%A3%80%E9%AA%8C%3A%20%E4%B8%89%E4%BB%B6%E5%A5%97%E4%B8%8E%E6%A0%B7%E6%9C%AC%E5%85%B3%22%5D%0A%20%20PERSIST%20--%3E%20DRAG%5B%22%E8%A1%8C%E4%B8%BA%E6%8D%9F%E8%80%97%E5%AF%B9%E8%B4%A6%3A%20MWR-TWR%22%5D%0A%20%20DRAG%20--%3E%20REPORT%5B%22%E5%8F%AF%E5%A4%8D%E7%AE%97%E7%9A%84%E7%BB%A9%E6%95%88%E6%8A%A5%E5%91%8A%22%5D%0A%20%20REPORT%20--%3E%7C%22%E5%85%88%E4%BE%8B%E4%B8%8E%E5%8F%A3%E5%BE%84%E5%9B%9E%E5%86%99%22%7C%20ACC%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把收束写成对照表：每课交付一个对象而不是一个知识点——口径字段、瀑布科目、曲线与修订档案、比率套装、基准条款、转移矩阵、缺口对账表。验收同样用三问，与做市课同构：绩效报告里的每个数字都能沿链回溯到账本与合同，链就是活的。与已修课程的接口逐个钉死：费用的复利算术在<a href="/quant/fees-compounding">费用对复合收益</a>，业绩费的期权结构在<a href="/quant/performance-fee-hwm">业绩费与高水位</a>；归因是收束之后的下一层算术，在<a href="/quant/brinson">Brinson 归因</a>与<a href="/quant/pf-attribution-deep">绩效归因的深化</a>；统计谦逊在<a href="/quant/deflated-sharpe">放气夏普</a>与主干<a href="/quant/performance-persistence">业绩持续性</a>。Sharpe 的算术给整门课程划上界：主动作为一个整体扣费后跑不赢被动——账户绩效能改善的，是整体内部的位置与损耗，不是整体对被动的算术。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>课程内部的机制主线：<strong>先钉测量，再谈评价；每个比较先声明「跟谁比、按谁的口径」</strong>。账户层与做市台同构，信息只进不丢：口径不丢毛净边界，瀑布不丢科目，曲线不丢估值层级与修订，基准不丢变更程序，对账不丢时点项。凡靠记忆与裁量补位的环节——「这个数大概是含分红的」「基准今年换了但差额不大」——都是绩效争议的案发地址。核算与评估的分工也在这条线上：核算单元（前三课）保证数字忠实，评估单元（后五课）保证比较公平；顺序不可倒置，因为公平的比较是忠实的数字的函数。</p>',4)),(A(),r(o,null,{default:a(()=>[B(t,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20CORE%5B%22%E6%A0%B8%E7%AE%97%E5%8D%95%E5%85%83%3A%20%E4%BF%9D%E5%BF%A0%E5%AE%9E%22%5D%20--%3E%20C1%5B%22%E5%8F%A3%E5%BE%84%3A%20%E6%AF%9B%E5%87%80%E8%BE%B9%E7%95%8C%E4%B8%8D%E4%B8%A2%22%5D%0A%20%20CORE%20--%3E%20C2%5B%22%E7%80%91%E5%B8%83%3A%20%E7%A7%91%E7%9B%AE%E4%B8%8D%E4%B8%A2%22%5D%0A%20%20CORE%20--%3E%20C3%5B%22%E6%9B%B2%E7%BA%BF%3A%20%E4%BF%AE%E8%AE%A2%E7%95%99%E7%97%95%E4%B8%8D%E4%B8%A2%22%5D%0A%20%20C3%20--%3E%20EVAL%5B%22%E8%AF%84%E4%BC%B0%E5%8D%95%E5%85%83%3A%20%E4%BF%9D%E5%85%AC%E5%B9%B3%22%5D%0A%20%20EVAL%20--%3E%20E1%5B%22%E6%AF%94%E7%8E%87%E4%B8%8E%E5%9F%BA%E5%87%86%3A%20%E8%B7%9F%E8%B0%81%E6%AF%94%2C%20%E6%8C%89%E8%B0%81%E5%8F%A3%E5%BE%84%22%5D%0A%20%20EVAL%20--%3E%20E2%5B%22%E5%AF%B9%E8%B4%A6%3A%20%E6%97%B6%E7%82%B9%E9%A1%B9%E4%B8%8D%E4%B8%A2%22%5D%0A%20%20EVAL%20--%3E%20GAP%7B%22%E5%93%AA%E4%B8%80%E7%8E%AF%E9%9D%A0%E8%AE%B0%E5%BF%86%E6%88%96%E8%A3%81%E9%87%8F%E8%A1%A5%E4%BD%8D%3F%22%7D%0A%20%20GAP%20--%3E%7C%22%E6%9C%89%22%7C%20CASE%5B%22%E7%BB%A9%E6%95%88%E4%BA%89%E8%AE%AE%E7%9A%84%E6%A1%88%E5%8F%91%E5%9C%B0%E5%9D%80%22%5D%0A%20%20GAP%20--%3E%7C%22%E6%B2%A1%E6%9C%89%22%7C%20AUDIT%5B%22%E5%8F%AF%E5%A4%8D%E7%AE%97%2C%20%E5%8F%AF%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<p><span class="marginnote">直觉类比：核算与评估的关系像田径比赛——先统一量尺和计时器（核算），才能比较谁跑得快（评估）。一个用公斤、一个用磅的举重比赛，名次再漂亮也没有意义；公平的比较是忠实的测量的函数，顺序反了全盘皆输。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课程刻意没有覆盖三块。其一，税：持有结构与实现时点对净值的侵蚀，<a href="/quant/tax-aware-portfolio">税务感知组合</a>专课处理。其二，监管报送与 GIPS 合规的认证细节：列示规范、陈述要求与核验流程，属于合规工程。其三，多管理人账户的合计与费用分摊：比单账户多出加权与归属两层问题。归因细节与风险归因各有专课。树序的下一课程转向宏观与跨资产策略，视角从账户换到资产；评价的仪器留在本课程，测量纪律留在每一张报告里。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>八课一条链：口径、瀑布、曲线、比率、基准、持续性、行为对账，环环可复算。</li><li>每课交付一个对象；验收三问——从哪来、谁改过、依据哪条——都指向文件。</li><li>机制主线：先钉测量再谈评价；核算保忠实，评估保公平，顺序不可倒置。</li><li>Sharpe 算术划上界：账户绩效改善的是整体内部的位置与损耗，不是整体输给被动的差额。</li><li>未覆盖的税、合规报送与多管理人合计各有专课，接口已标出。</li><li>出处：Sharpe, <em>Financial Analysts Journal</em>, 1991；口径与判据据 CFA Institute, <em>Global Investment Performance Standards</em> 及绩效评估实务整理。</li></ul>',5))])}const F=i(p,[["render",d]]);export{c as __pageData,F as default};
